// Textos con datos variables (cantidades, nombres, precios, pesos...). Cada patrón recibe la
// coincidencia y `tr` (traduce un trozo o lo deja tal cual).
window.HA_I18N_PATTERNS = (function () {
  function list(s, tr, map) {
    return s
      .split(", ")
      .map(function (x) {
        return map[x] || tr(x);
      })
      .join(", ");
  }
  var CART_MISSING = { "tu nombre": "your name", "un teléfono": "a phone number", "la dirección": "the address", "el código postal": "the postcode", "la ciudad": "the city" };
  var DESIGN_MISSING = { nombre: "name", "teléfono": "phone", "dirección": "address", "código postal": "postcode", ciudad: "city", "forma de pago": "payment method" };
  var SHIP = { "Envío ordinario": "Standard mail", "Envío certificado": "Registered mail", "Paq Light Internacional": "Paq Light Internacional", "Envío a confirmar": "Shipping to be confirmed" };
  function items(n) {
    return n === "1" ? "1 item" : n + " items";
  }
  return [
    [/^(\d+) productos?$/, function (m) { return m[1] === "1" ? "1 product" : m[1] + " products"; }],
    [/^Cesta, (\d+) artículos?$/, function (m) { return "Basket, " + items(m[1]); }],
    [/^(.+) añadido a la cesta\. Cesta: (\d+) artículos?\.$/, function (m, tr) { return tr(m[1]) + " added to the basket. Basket: " + items(m[2]) + "."; }],
    [/^Quitar una unidad de (.+)$/, function (m, tr) { return "Remove one of " + tr(m[1]); }],
    [/^Añadir una unidad de (.+)$/, function (m, tr) { return "Add one more " + tr(m[1]); }],
    [/^Cantidad de (.+)$/, function (m, tr) { return "Quantity of " + tr(m[1]); }],
    [/^Quitar (.+) de la cesta$/, function (m, tr) { return "Remove " + tr(m[1]) + " from the basket"; }],
    [/^(Envío ordinario|Envío certificado|Paq Light Internacional|Envío a confirmar) \((.+)\)$/, function (m, tr) { return SHIP[m[1]] + " (" + tr(m[2]) + ")"; }],
    [/^Los envíos fuera de España van por Paq Light Internacional de Correos, con número de seguimiento\. Peso aproximado del pedido: (.+)\.$/,
      "Shipments outside Spain go by Correos Paq Light Internacional, with tracking. Approximate order weight: $1."],
    [/^El pedido pesa unos (.+) y supera los 2 kg del Paq Light Internacional: te confirmaremos el coste del envío por paquetería antes de que pagues\.$/,
      "The order weighs about $1, over the 2 kg limit for Paq Light Internacional: we'll confirm the parcel shipping cost before you pay."],
    [/^Falta: (.+)\.$/, function (m, tr) { return "Missing: " + list(m[1], tr, DESIGN_MISSING) + "."; }],
    [/^Falta (.+)\.$/, function (m, tr) { return "Missing: " + list(m[1], tr, CART_MISSING) + "."; }],
    [/^Pedido (\S+) recibido\.$/, "Order $1 received."],
    [/^Enviando la confirmación a <b>(.+)<\/b>…$/, "Sending the confirmation to <b>$1</b>…"],
    [/^Te hemos enviado la confirmación a <b>(.+)<\/b>\.$/, "We've sent the confirmation to <b>$1</b>."],
    [/^Precio anterior: (.+)$/, "Previous price: $1"],
    [/^Precio actual: (.+)$/, "Current price: $1"],
    [/^Más información de (.+)$/, function (m, tr) { return "More information about " + tr(m[1]); }],
    [/^Añadir (.+) a la cesta$/, function (m, tr) { return "Add " + tr(m[1]) + " to the basket"; }],
    [/^Total estimado: (.+) \((.+)\/unidad\)$/, "Estimated total: $1 ($2/unit)"],
    [/^Procesando (.+)\.\.\.$/, "Processing $1..."],
    [/^Diseño cargado: (.+) \(a su tamaño real: (.+) mm\)\.$/, "Design loaded: $1 (at its real size: $2 mm)."],
    [/^Diseño cargado: (.+)\.$/, "Design loaded: $1."],
    [/^Su tamaño original \((.+) mm\) no cabe en el rango permitido \((.+)–(.+) mm\), así que se ha ajustado a (.+) mm\.$/,
      "Its original size ($1 mm) doesn't fit the allowed range ($2–$3 mm), so it has been adjusted to $4 mm."],
    [/^El tamaño original del diseño \((.+) mm\) no cabe en el rango permitido \((.+)–(.+) mm\), así que se ha ajustado a (.+) mm\.$/,
      "The design's original size ($1 mm) doesn't fit the allowed range ($2–$3 mm), so it has been adjusted to $4 mm."],
    [/^Falta la cantidad: el pedido mínimo es de (\d+) unidades\.$/, "Quantity missing: the minimum order is $1 units."],
    [/^Para más de (\d+) unidades, escríbenos directamente y te preparamos un presupuesto a medida\.$/,
      "For more than $1 units, contact us directly and we'll prepare a tailored quote."],
    [/^¡Solicitud enviada! Código (\S+)\. Te contactaremos con un presupuesto\. Para confirmárnosla, envíanos también el resumen por WhatsApp\.$/,
      "Request sent! Code $1. We'll get back to you with a quote. To confirm it, please also send us the summary on WhatsApp."],
    [/^¡Solicitud enviada! Código (\S+)\. Te contactaremos con un presupuesto\.$/, "Request sent! Code $1. We'll get back to you with a quote."],
    [/^No se pudo enviar: Revisa que los datos no sean demasiado largos \(nombre, dirección, notas\.\.\.\) e inténtalo de nuevo\. Si sigue fallando, escríbenos por (WhatsApp|email)\.$/,
      function (m) { return "Couldn't send: check the details aren't too long (name, address, notes...) and try again. If it keeps failing, " + (m[1] === "email" ? "email us." : "message us on WhatsApp."); }],
    [/^No se pudo enviar: (.+)$/, function (m, tr) { return "Couldn't send: " + tr(m[1]); }],
  ];
})();
